CREATE OR ALTER PROCEDURE [dbo].[uspInventoryPolicy_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @IngredientId UNIQUEIDENTIFIER = NULL
	, @WarehouseId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @MinimumStock DECIMAL(18,4) = NULL
	, @MaximumStock DECIMAL(18,4) = NULL
	, @SafetyStock DECIMAL(18,6) = NULL
	, @UseFefo BIT = NULL
	, @ExpiryWarningDays INT = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[IngredientId]
			, t.[WarehouseId]
			, t.[MinStock]
			, t.[MaxStock]
			, t.[SafetyStock]
			, t.[ReorderPoint]
			, t.[CriticalLevel]
			, t.[LeadTimeDays]
			, t.[Status]
			, t.[MinimumStock]
			, t.[MaximumStock]
			, t.[UseFefo]
			, t.[ExpiryWarningDays]
			, t.[CreatedDate]
		FROM [dbo].[InventoryPolicie] AS t
		
		WHERE 1 = 1
			AND (@IngredientId IS NULL OR t.[IngredientId] = @IngredientId)
			AND (@WarehouseId IS NULL OR t.[WarehouseId] = @WarehouseId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@MinimumStock IS NULL OR t.[MinimumStock] = @MinimumStock)
			AND (@MaximumStock IS NULL OR t.[MaximumStock] = @MaximumStock)
			AND (@SafetyStock IS NULL OR t.[SafetyStock] = @SafetyStock)
			AND (@UseFefo IS NULL OR t.[UseFefo] = @UseFefo)
			AND (@ExpiryWarningDays IS NULL OR t.[ExpiryWarningDays] = @ExpiryWarningDays)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'ingredientId' THEN r.[IngredientId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'ingredientId' THEN r.[IngredientId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'warehouseId' THEN r.[WarehouseId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'warehouseId' THEN r.[WarehouseId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'minStock' THEN r.[MinStock] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'minStock' THEN r.[MinStock] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'maxStock' THEN r.[MaxStock] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'maxStock' THEN r.[MaxStock] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'safetyStock' THEN r.[SafetyStock] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'safetyStock' THEN r.[SafetyStock] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'reorderPoint' THEN r.[ReorderPoint] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'reorderPoint' THEN r.[ReorderPoint] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'criticalLevel' THEN r.[CriticalLevel] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'criticalLevel' THEN r.[CriticalLevel] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'leadTimeDays' THEN r.[LeadTimeDays] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'leadTimeDays' THEN r.[LeadTimeDays] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'minimumStock' THEN r.[MinimumStock] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'minimumStock' THEN r.[MinimumStock] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'maximumStock' THEN r.[MaximumStock] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'maximumStock' THEN r.[MaximumStock] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'useFefo' THEN r.[UseFefo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'useFefo' THEN r.[UseFefo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'expiryWarningDays' THEN r.[ExpiryWarningDays] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'expiryWarningDays' THEN r.[ExpiryWarningDays] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
